import numpy as np
from pymoo.algorithms.soo.nonconvex.pso import PSO
from pymoo.core.problem import ElementwiseProblem
from pymoo.optimize import minimize

OPTIMIZER_FAMILY = "pymoo_pso"
SEEDS_SCOUT = [23]
SEEDS_REFINE = [23, 24, 25]
SCOUT_EVALS = 288
MID_REFINE_EVALS = 96
MID_REOPEN_MARGIN = 96


class Evaluator(BaseEvaluator):
    """Light TODD ab-initio: TOHPE-driven search with many optimizer iterations."""

    def __init__(self, seeds, **kwargs):
        super().__init__(**kwargs)
        self._seeds = seeds

    def float_range(self, low: float, high: float) -> float:
        return self.map_par(lambda x: low + (high - low) / (1.0 + np.exp(-np.clip(float(x), -8.0, 8.0) / 2.5)))

