    """TOHPE-heavy ab-initio with rank-scheduled beamwidth and capped TODD."""

    def float_range(self, low: float, high: float) -> float:
        return self.map_par(
            lambda x: low + (high - low) / (1.0 + np.exp(-np.clip(float(x), -8.0, 8.0) / 2.5))
        )

