        )
        # Enhanced TOHPE: more candidates to increase cheap-source yield
        self.set_tohpe_search(
            TohpeSearch(
                SamplingBudget(
                    one_hot=24, sparse=4, dense=0, sparse_max_weight=2
                ),
                SourcePool(keep=8, reserve=1),
                z_choices=4,
            )
        )
        self.set_todd_search(
            ToddSearch(
                SamplingBudget(
                    one_hot=8, sparse=2, dense=0, sparse_max_weight=2
                ),
                SourcePool(keep=self.int_range(6, 12), reserve=2),
                actions_per_bucket=2,
                buckets=ZBucketSearch(
                    min_buckets=32,
                    max_buckets=todd_cap,
                    limit_bucket=todd_cap,
                ),
            )
        )

    def __call__(self, params: Iterable[float]) -> float:
        values = np.asarray(
            self.run(params, self._seeds), dtype=float
        )
        return float(values.min() + 0.02 * values.std())


class Problem(ElementwiseProblem):
    def __init__(self, evaluator: Evaluator):
        n = len(evaluator.extract_active())
        super().__init__(
            n_var=n, n_obj=1, xl=np.full(n, -1.0), xu=np.full(n, 1.0)
        )
        self.evaluator = evaluator

    def _evaluate(self, x, out, *args, **kwargs):
        out["F"] = self.evaluator(np.asarray(x, dtype=float))


def optimize(
    evaluator: Evaluator, evaluations: int, seed: int
) -> np.ndarray:
    algorithm = PSO(
        pop_size=8, w=0.7, c1=0.4, c2=0.4, adaptive=False
    )
    result = minimize(
        Problem(evaluator),
        algorithm,
        termination=("n_eval", evaluations),
        seed=seed,
        verbose=False,
    )
    return np.asarray(
        result.X
        if result.X is not None
