                    SamplingBudget(one_hot=0, sparse=0, dense=0, sparse_max_weight=2),
                    SourcePool(keep=0, reserve=0),
                    actions_per_bucket=0,
                    buckets=ZBucketSearch(min_buckets=0, max_buckets=0, limit_bucket=0),
                ),
                ToddSearch(
                    SamplingBudget(one_hot=8, sparse=2, dense=0, sparse_max_weight=2),
                    SourcePool(keep=self.int_range(4, 8), reserve=1),
                    actions_per_bucket=1,
                    buckets=ZBucketSearch(
                        min_buckets=8,
                        max_buckets=48,
                        limit_bucket=48,
                    ),
                ),
            ]
        )

    def __call__(self, params: Iterable[float]) -> float:
        values = np.asarray(self.run(params, self._seeds), dtype=float)
        return float(values.min() + 0.02 * values.std())


class Problem(ElementwiseProblem):
    def __init__(self, evaluator: Evaluator):
        n = len(evaluator.extract_active())
        super().__init__(n_var=n, n_obj=1, xl=np.full(n, -1.0), xu=np.full(n, 1.0))
        self.evaluator = evaluator

    def _evaluate(self, x, out, *args, **kwargs):
        out["F"] = self.evaluator(np.asarray(x, dtype=float))


def optimize(evaluator: Evaluator, evaluations: int, seed: int) -> np.ndarray:
    # smaller PSO swarm to reallocate per-eval cost into more iterations/seeds
    algorithm = PSO(pop_size=16, w=0.7, c1=0.6, c2=0.6, adaptive=True)
    result = minimize(Problem(evaluator), algorithm, termination=("n_eval", evaluations), seed=seed, verbose=False)
    return np.asarray(result.X if result.X is not None else evaluator.extract_active(), dtype=float)


def entrypoint():
    evaluator = Evaluator(seeds=SEEDS_SCOUT, path_name="init", max_depth=500)
    params = optimize(evaluator, SCOUT_EVALS, seed=23)
    evaluator._seeds = SEEDS_REFINE
    params = evaluator.set_up_new_init(0, rank_thr=evaluator.best_rank + MID_REOPEN_MARGIN, xopt=params)
    if params is not None:
        optimize(evaluator, MID_REFINE_EVALS, seed=26)
    return evaluator.get_best()
"}
